/**
 * NavMesh - Navigation mesh data structure
 *
 * Polygon-based navigation mesh with adjacency graph for A* pathfinding.
 * Uses spatial hash for fast point-to-polygon queries.
 *
 * **Usage**
 *
 * ```js
 * const navMesh = new NavMesh();
 * navMesh.initFromData(compiledData);
 *
 * const polygon = navMesh.findPolygonAt(x, z);
 * const neighbors = navMesh.getNeighbors(polygon);
 * ```
 *
 * @class NavMesh
 * @short Navigation mesh with polygon adjacency graph
 * @category Navigation
 * @tags NavMesh, Polygon, Pathfinding, Spatial Index
 */
export class NavMesh {
    /**
     * All polygons in the navmesh.
     * @type {Array<NavMeshPolygon>}
     */
    polygons: Array<NavMeshPolygon>;
    /**
     * Edge hash to portal data for adjacency.
     * @type {Map<string, {poly1Index: number, poly2Index: number, portal: Object}>}
     */
    edges: Map<string, {
        poly1Index: number;
        poly2Index: number;
        portal: any;
    }>;
    /**
     * Bounding box of navmesh.
     * @type {THREE.Box3}
     */
    bounds: THREE.Box3;
    /**
     * Spatial hash for fast polygon lookup.
     * Maps cell key to array of polygon indices.
     * @type {Map<string, Array<number>>}
     * @private
     */
    private _spatialGrid;
    /**
     * Cell size for spatial hash.
     * @type {number}
     * @private
     */
    private _spatialCellSize;
    /**
     * Whether navmesh is initialized.
     * @type {boolean}
     * @private
     */
    private _initialized;
    /**
     * Three.js-style type flag.
     * @type {boolean}
     */
    isNavMesh: boolean;
    /**
     * Initialize navmesh from serialized data (from main thread).
     *
     * @param {Object} data - Serialized navmesh data.
     * @param {Array<{vertices: Array, normal: Object}>} data.polygons - Polygon data.
     * @param {Array<Array>} [data.edges] - Edge adjacency data (array of [edgeKey, edgeInfo] pairs).
     */
    initFromData(data: {
        polygons: Array<{
            vertices: any[];
            normal: any;
        }>;
        edges?: Array<any[]>;
    }): void;
    /**
     * Find which polygon contains a world position.
     * Uses spatial hash for fast O(1) average lookup.
     *
     * @param {number} x - World X coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {NavMeshPolygon|null} Containing polygon or null.
     */
    findPolygonAt(x: number, z: number): NavMeshPolygon | null;
    /**
     * Find nearest polygon to a world position.
     * Fallback when point is outside all polygons.
     *
     * @param {number} x - World X coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {NavMeshPolygon|null} Nearest polygon or null.
     */
    findNearestPolygon(x: number, z: number): NavMeshPolygon | null;
    /**
     * Get adjacent polygons sharing an edge.
     *
     * @param {NavMeshPolygon} polygon - Source polygon.
     * @returns {Array<{polygon: NavMeshPolygon, portal: Object}>} Neighbor data.
     */
    getNeighbors(polygon: NavMeshPolygon): Array<{
        polygon: NavMeshPolygon;
        portal: any;
    }>;
    /**
     * Build adjacency graph from polygon edges.
     * Two polygons are neighbors if they share exactly 2 vertices (an edge).
     *
     * @private
     */
    private _buildAdjacencyGraph;
    /**
     * Build spatial hash index for fast polygon lookup.
     *
     * @private
     */
    private _buildSpatialIndex;
    /**
     * Compute navmesh bounding box.
     *
     * @private
     */
    private _computeBounds;
    /**
     * Get spatial hash key for position.
     *
     * @param {number} x - World X.
     * @param {number} z - World Z.
     * @returns {string} Cell key.
     * @private
     */
    private _getSpatialKey;
    /**
     * Create canonical edge hash for matching.
     * Sorts vertices to ensure consistent hash regardless of direction.
     *
     * @param {Object} v1 - First vertex.
     * @param {Object} v2 - Second vertex.
     * @returns {string} Edge hash.
     * @private
     */
    private _edgeHash;
    /**
     * Get debug info.
     *
     * @returns {Object} Debug information.
     */
    getDebugInfo(): any;
    /**
     * Clear navmesh data.
     */
    clear(): void;
    /**
     * Whether navmesh is initialized.
     * @type {boolean}
     * @readonly
     */
    readonly get initialized(): boolean;
    /**
     * Number of polygons.
     * @type {number}
     * @readonly
     */
    readonly get polygonCount(): number;
}
/**
 * NavMeshPolygon - Single convex polygon in navigation mesh
 *
 * Represents a walkable polygon with vertices, centroid, and neighbor connectivity.
 * Used for polygon-graph A* pathfinding.
 *
 * @class NavMeshPolygon
 * @short Single convex polygon in navmesh
 * @category Navigation
 * @tags NavMesh, Polygon, Pathfinding
 */
export class NavMeshPolygon {
    /**
     * Create a navmesh polygon.
     *
     * @param {Object} data - Polygon data from serialization.
     * @param {Array<{x: number, y: number, z: number}>} data.vertices - Polygon vertices.
     * @param {{x: number, y: number, z: number}} [data.normal] - Surface normal.
     * @param {number} index - Polygon index in navmesh.
     */
    constructor(data: {
        vertices: Array<{
            x: number;
            y: number;
            z: number;
        }>;
        normal?: {
            x: number;
            y: number;
            z: number;
        };
    }, index: number);
    /**
     * Polygon index in navmesh.
     * @type {number}
     */
    index: number;
    /**
     * Polygon vertices in world space.
     * @type {Array<{x: number, y: number, z: number}>}
     */
    vertices: Array<{
        x: number;
        y: number;
        z: number;
    }>;
    /**
     * Surface normal.
     * @type {{x: number, y: number, z: number}}
     */
    normal: {
        x: number;
        y: number;
        z: number;
    };
    /**
     * Polygon centroid (average of vertices).
     * @type {{x: number, y: number, z: number}}
     */
    centroid: {
        x: number;
        y: number;
        z: number;
    };
    /**
     * Ground height at centroid.
     * @type {number}
     */
    groundY: number;
    /**
     * Adjacent polygons with portal edges.
     * Populated by NavMesh._buildAdjacencyGraph().
     * @type {Array<{polygon: NavMeshPolygon, portal: {left: {x,y,z}, right: {x,y,z}}}>}
     */
    neighbors: Array<{
        polygon: NavMeshPolygon;
        portal: {
            left: {
                x: any;
                y: any;
                z: any;
            };
            right: {
                x: any;
                y: any;
                z: any;
            };
        };
    }>;
    /**
     * Check if point is inside polygon (2D projection on XZ plane).
     * Uses cross product sign test for convex polygons.
     *
     * @param {number} x - World X coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {boolean} True if point is inside.
     */
    containsPoint(x: number, z: number): boolean;
    /**
     * Get Y height at position within polygon using barycentric interpolation.
     *
     * @param {number} x - World X coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {number} Interpolated Y height.
     */
    getHeightAt(x: number, z: number): number;
    /**
     * Compute polygon centroid.
     *
     * @returns {{x: number, y: number, z: number}} Centroid position.
     * @private
     */
    private _computeCentroid;
}
